function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500)}function setState(s){state=s;$('#neural-state').textContent=s.toUpperCase();$('#orb-status').textContent=s==='Ready'?'READY TO CONNECT':s.toUpperCase();$('#orb-title').textContent={Ready:'What are we exploring?',Thinking:'Connecting the dots…',Working:'Following your intent…',Speaking:'Here’s what I found.',Listening:'I’m listening.',Interrupted:'A fresh direction.'}[s]||s;}function addMessage(role,text){$('.core-panel').classList.add('has-chat');const el=document.createElement('div');el.className='message '+role;const label=document.createElement('span');label.className='role';label.textContent=role==='user'?'YOU':role==='system'?'SESSION':'NOVA';el.append(label,document.createTextNode(text));$('#messages').append(el);$('#messages').scrollTop=$('#messages').scrollHeight;return el}function stopAudio(){player.stop();audioChain=Promise.resolve();if('speechSynthesis'in window)speechSynthesis.cancel();}async function stop(){voiceEpoch++;stopAudio();if(approval){approval=null;$('#approval-dialog').close()}await bridge.cancel();setState('Interrupted');$('#voice-sub').textContent='Stopped. Ready for your updated request.'}
const player=new PCMPlayer(s=>{if(s==='playing'){setState('Speaking');$('#latency').textContent=Math.round(performance.now()-turnStart)+' ms';$('#voice-provider').textContent='Rime · Coda';$('#provider-label').textContent='RIME LIVE';$('#voice-sub').textContent='Speaking · you can interrupt';}if(s==='ended'){setState(voiceOn?'Listening':'Ready');$('#voice-sub').textContent=voiceOn?'Listening for your next thought.':'Ready for your next thought.'}});
bridge.onEvent(async e=>{if(e.type==='cancel'){currentTurn=-1;stopAudio();if(approval){approval=null;$('#approval-dialog').close()}}if(e.type==='start'){currentTurn=e.turn;turnStart=performance.now();addMessage('user',e.text);setState('Thinking');$('#latency').textContent='—'}if(e.type==='state'&&e.turn===currentTurn){if(e.state!=='Ready'||!player.started)setState(voiceOn&&e.state==='Ready'?'Listening':e.state)}if(e.type==='response'&&e.turn===currentTurn){addMessage('assistant',e.text);if(!desktop&&demoSpeech&&'speechSynthesis'in window){const utter=new SpeechSynthesisUtterance(e.text);utter.onstart=()=>{if(e.turn===currentTurn){setState('Speaking');$('#latency').textContent=Math.round(performance.now()-turnStart)+' ms';$('#voice-provider').textContent='Browser fallback'}};utter.onend=()=>{if(e.turn===currentTurn){bridge.heard(e.turn);setState(voiceOn?'Listening':'Ready')}};speechSynthesis.speak(utter)}}if(e.type==='audio'&&e.turn===currentTurn){const id=e.turn;audioChain=audioChain.then(()=>{if(id===currentTurn)return player.push(e.chunk)}).catch(err=>toast('Audio playback failed: '+err.message))}if(e.type==='audio-end'&&e.turn===currentTurn){const id=e.turn;audioChain.then(()=>{if(id===currentTurn)player.finish(()=>bridge.heard(id))})}if(e.type==='policy'){$('#policy-title').textContent={allow:'Action allowed',approval:'Your approval is needed',block:'Action blocked'}[e.decision]||e.decision;$('#policy-reason').textContent=e.reason;$('#latest-activity').textContent=e.rule+' · '+e.reason}if(e.type==='approval'){approval=e;$('#approval-reason').textContent=e.reason;$('#approval-preview').textContent=e.action.args.title+'\n\n'+e.action.args.content;$('#approval-dialog').showModal()}if(e.type==='tool'){await refreshMemory();$('#latest-activity').textContent=e.name==='save_memory'?'A new memory was saved with your approval.':(e.count??0)+' matching memories found.'}if(e.type==='error'){addMessage('system',e.message);toast(e.message);setState('Ready')}if(e.type==='speech-error'){$('#voice-provider').textContent='Text only · Rime unavailable';$('#provider-label').textContent='RIME ERROR';addMessage('system','Speech unavailable: '+e.message);setState('Ready')}if(e.type==='heard')$('#latest-activity').textContent='Playback completed for turn '+e.turn+'.';});
async function send(text){if(!text.trim())return;voiceEpoch++;stopAudio();$('#message-input').value='';view('command');if(desktop)await player.unlock().catch(()=>{});try{await bridge.send(text)}catch(e){toast(e.message)}}$('#composer').onsubmit=e=>{e.preventDefault();send($('#message-input').value)};$('#message-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e.target.value)}};$$('[data-prompt]').forEach(b=>b.onclick=()=>send(b.dataset.prompt));$('#interrupt').onclick=stop;async function decide(yes){if(!approval)return;const id=approval.approvalId;approval=null;$('#approval-dialog').close();try{await bridge.approve(id,yes)}catch(e){toast(e.message)}}$('#approve').onclick=()=>decide(true);$('#deny').onclick=()=>decide(false);$('#approval-dialog').oncancel=e=>{e.preventDefault();decide(false)};
async function refreshMemory(){memory=await bridge.memory();if(!memory.some(m=>m.id===selected))selected=memory[0]?.id;$('#memory-count').textContent=memory.length;drawGraphs();renderMemoryList();}function drawGraphs(){for(const [id,large]of [['#mini-network',false],['#full-network',true]])renderGraph($(id),memory,selected,choose,{large,zoom:large?zoom:1});const m=memory.find(x=>x.id===selected);if(!m)return;$('#selected-title').textContent=m.title;$('#selected-description').textContent=m.content;const detail=$('#memory-detail');detail.replaceChildren();const h=document.createElement('h3'),p=document.createElement('p'),s=document.createElement('small');h.textContent=m.title;p.textContent=m.content;s.textContent='Source: '+m.source+(m.createdAt?' · '+new Date(m.createdAt).toLocaleDateString():'');detail.append(h,p,s)}function choose(id){selected=id;drawGraphs();renderMemoryList()}function renderMemoryList(){const q=$('#memory-search').value.toLowerCase(),list=$('#memory-list');list.replaceChildren();const matches=memory.filter(m=>(m.title+' '+m.content).toLowerCase().includes(q));if(!matches.length){const p=document.createElement('p');p.className='empty';p.textContent='No matching memories.';list.append(p)}for(const m of matches){const b=document.createElement('button');b.className='memory-row'+(m.id===selected?' active':'');b.textContent=m.title;const small=document.createElement('small');small.textContent=m.kind+' · '+(m.links?.length||0)+' connections';b.append(small);b.onclick=()=>choose(m.id);list.append(b)}}$('#memory-search').oninput=renderMemoryList;$('#zoom-in').onclick=()=>{zoom=Math.min(1.7,zoom+.15);drawGraphs()};$('#zoom-out').onclick=()=>{zoom=Math.max(.55,zoom-.15);drawGraphs()};$('#zoom-reset').onclick=()=>{zoom=1;drawGraphs()};$('#new-memory').onclick=()=>$('#memory-dialog').showModal();$('#cancel-memory').onclick=()=>$('#memory-dialog').close();$('#memory-form').onsubmit=e=>{e.preventDefault();const title=$('#note-title').value.trim(),content=$('#note-content').value.trim();if(!title||!content)return;$('#memory-dialog').close();send('Remember exactly: '+JSON.stringify({title,content}));$('#memory-form').reset()};
async function refreshAudit(){const audit=await bridge.audit(),list=$('#audit-list');list.replaceChildren();if(!audit.length){list.innerHTML='<div class="empty">No actions recorded yet. Start a task to build your audit trail.</div>';return}for(const e of audit.slice().reverse()){const row=document.createElement('div');row.className='audit-row';const kind=document.createElement('span');kind.className='audit-kind';kind.textContent=e.type;const body=document.createElement('div');body.textContent=e.reason||e.message||e.name||({cancel:'Turn interrupted · obsolete work fenced',approved:'Exact action approved',heard:'Spoken response completed'}[e.type])||e.type;const detail=document.createElement('p');detail.textContent=e.action?JSON.stringify(e.action):e.text||('Turn '+(e.turn??'—'));body.append(detail);const time=document.createElement('time');time.textContent=new Date(e.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});row.append(kind,body,time);list.append(row)}}function download(name,content){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#export-audit').onclick=async()=>download('nova-aegis-audit.json',JSON.stringify(await bridge.audit(),null,2));$('#try-block').onclick=()=>send('Delete all my memories');
const wave=$('#waveform');for(let i=0;i<45;i++){const b=document.createElement('i');b.style.height=(3+Math.sin(i*1.7)**2*13)+'px';b.style.animationDelay=(i%7)*.07+'s';wave.append(b)}function voiceUI(on){voiceOn=on;$('#voice-toggle').innerHTML='<span data-icon="'+(on?'stop':'mic')+'"></span> '+(on?'End session':'Start session');icons($('#voice-toggle'));$('#mic').classList.toggle('recording',on);$('#mic').setAttribute('aria-label',on?'End voice session':'Start voice session');wave.classList.toggle('listening',on);$('#voice-sub').textContent=on?'Listening · headphones recommended':'Your next thought starts here.';setState(on?'Listening':'Ready')}
const capture=new VoiceCapture({onStart:()=>{stop();setState('Listening');$('#voice-sub').textContent='Listening to your update…'},onTurn:async bytes=>{const epoch=voiceEpoch;$('#voice-sub').textContent='Transcribing locally…';const text=await bridge.transcribe(bytes);if(epoch!==voiceEpoch||!voiceOn)return;if(text)await send(text)},onLevel:level=>{wave.style.opacity=String(Math.min(1,.35+level*8))},onError:e=>{toast('Voice input: '+e.message);$('#voice-sub').textContent='Recognition failed. Type or try again.'}});
async function toggleVoice(){if(voiceOn){recognitionWanted=false;recognition?.stop();capture.stop();await stop();voiceUI(false);return}if(desktop){try{await player.unlock();await capture.start();voiceUI(true);toast(hasRime?'Voice session started. Use headphones to reduce echo.':'Microphone active; Rime is not configured. Responses will remain text-only.')}catch(e){toast('Microphone could not start: '+e.message)}return}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Voice input is not supported in this browser. The desktop app uses a local whisper.cpp server.');return}recognition=new Speech();recognition.lang='en-US';recognition.continuous=true;recognition.interimResults=true;recognitionWanted=true;let spoken=false;recognition.onresult=e=>{let final='';for(let i=e.resultIndex;i<e.results.length;i++){if(!spoken){spoken=true;stop()}if(e.results[i].isFinal)final+=e.results[i][0].transcript}if(final.trim()){spoken=false;send(final)}};recognition.onend=()=>{if(recognitionWanted){try{recognition.start()}catch{}}else voiceUI(false)};recognition.onerror=e=>{if(['not-allowed','service-not-allowed','audio-capture'].includes(e.error)){recognitionWanted=false;voiceUI(false);toast('Browser speech recognition unavailable: '+e.error+'. You can still type.')}};try{recognition.start();voiceUI(true);toast('Browser recognition active. This demo is not the Rime desktop voice path.')}catch(e){recognitionWanted=false;toast(e.message)}}$('#mic').onclick=$('#voice-toggle').onclick=toggleVoice;$('#demo-speech').onchange=e=>{demoSpeech=e.target.checked;$('#provider-label').textContent=demoSpeech?'BROWSER FALLBACK':'VOICE OFF';$('#voice-provider').textContent=demoSpeech?'Browser fallback':'Not connected';if(!demoSpeech&&'speechSynthesis'in window)speechSynthesis.cancel();if(demoSpeech)toast('Browser speech fallback enabled. Rime is not active in this demo.')};
async function connections(){if(!desktop){$('#connection-result').textContent='Interactive web demo. Download the desktop source to use Ollama, local speech recognition, and Rime.';return}$('#connection-result').textContent='Checking local services and the live Rime voice catalog…';try{const s=await bridge.status();hasRime=s.rime;$('#model-label').textContent=s.ollama?s.config.model:'OLLAMA OFFLINE';$('#provider-label').textContent=s.rime?(s.voice?'RIME CONFIGURED':'RIME CHECK FAILED'):'RIME NOT SET';$('#voice-provider').textContent=s.rime?'Rime · '+s.config.rimeModel:'Not configured';for(const [k,v]of Object.entries(s.config)){const el=$('#settings-form').elements.namedItem(k);if(el)el.value=v}$('#model-options').replaceChildren();for(const model of s.models){const o=document.createElement('option');o.value=model;$('#model-options').append(o)}$('#connection-result').textContent=(s.ollama?'Ollama connected. Models: '+s.models.join(', '):'Ollama is not reachable.')+'\n'+(s.voice?'Rime voice found in live catalog. Audio synthesis still requires a live request.':s.rime?'Rime key present; catalog verification failed.':'Rime key missing. Set RIME_API_KEY before starting the app.')+'\nSTT is checked on first microphone turn.'+(s.error?'\n'+s.error:'')}catch(e){$('#connection-result').textContent=e.message}}
$('#check-connections').onclick=connections;$('#settings-form').onsubmit=async e=>{e.preventDefault();try{await bridge.configure(Object.fromEntries(new FormData(e.target)));await connections();toast('Connections saved.')}catch(e){toast(e.message)}};
async function stress(){if(stressRunning)return;view('voice');if(desktop){toast('For the live stress case, set the documented fixture delay and run the desktop acceptance procedure.');$('#stress-result').textContent='Desktop live test: use the procedure in RIME_EVIDENCE.md. Measure speaker output with loopback capture; no acoustic performance is inferred from this screen.';return}stressRunning=true;$('#run-stress').disabled=true;$('#stress-result').textContent='Running: five-second delayed memory lookup → interrupt after 1.2 seconds → new AEGIS request.';let oldTurn=null,newTurn=null,stale=0;const events=[];const off=bridge.onEvent(e=>{events.push(e);if(e.type==='start'){if(oldTurn===null)oldTurn=e.turn;else newTurn=e.turn}if(newTurn&&e.turn===oldTurn&&['response','audio','tool'].includes(e.type))stale++});try{bridge.runtime.delay=5000;const old=bridge.send('Search memory for voice');await new Promise(r=>setTimeout(r,1200));const t=performance.now();bridge.cancel();const cancelTime=performance.now()-t;bridge.runtime.delay=0;await bridge.send('Search memory for AEGIS');await old;await new Promise(r=>setTimeout(r,100));$('#stress-result').textContent=(stale===0?'PASS':'FAIL')+' · simulated stale-result isolation\nObsolete responses after interruption: '+stale+'\nCancellation dispatch: '+cancelTime.toFixed(2)+' ms (JavaScript only)\nUpdated task: AEGIS memory search completed.\nNot an acoustic stop-time measurement. No Rime audio or microphone was used.';$('#latest-activity').textContent='Interruption fixture completed. Inspect Voice studio for scope and results.'}catch(e){$('#stress-result').textContent='Test failed: '+e.message}finally{off();bridge.runtime.delay=0;stressRunning=false;$('#run-stress').disabled=false}}
$('#run-stress').onclick=stress;$('#try-interruption').onclick=()=>view('voice');if(desktop){$('#mode-label').textContent='Electron · local workspace';$('#footer-mode').textContent='DESKTOP WORKSPACE · LOCAL MEMORY';$('#settings-mode').textContent='ELECTRON';$('.toggle-row').hidden=true;$('#source-download').hidden=true;$('#core-mode').textContent='LOCAL OLLAMA INTELLIGENCE'}else{$('#settings-mode').textContent='WEB DEMO';$('#settings-form').querySelectorAll('input,select,button[type="submit"]').forEach(e=>e.disabled=true)}await refreshMemory();await connections();addEventListener('beforeunload',()=>{capture.stop();stopAudio()});
